#!/usr/bin/env python3
"""Differential test with several shapes and wide demand ranges."""
import json, random, sys, time
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
import analyze
from analyze import parse_request, solve
from brute import brute, compare
import gen
from difftest import check_witness

SHAPES = [(3,1,30),(3,1,60),(2,2,20),(2,1,100),(1,4,20),(4,1,20),(2,3,12),(3,2,8)]

def main():
    n=int(sys.argv[1]); seed=int(sys.argv[2])
    rnd=random.Random(seed); bad=0; stats={}; slowest=0; t0=time.time(); done=0; skipped=0
    kstats={}
    while done < n:
        C,S,B = rnd.choice(SHAPES)
        raw = gen.gen_instance(rnd, max_nodes=rnd.choice([2,3,4,5,6]),
                               max_edges=rnd.choice([3,6,9]),
                               max_coms=C, max_snaps=S,
                               max_doms=rnd.choice([0,2,3,5]),
                               max_bound=B, max_obs=rnd.choice([2,5,9]),
                               hard=rnd.random()<0.6)
        # widen bounds to exercise LP refinement over big ranges
        for sp in raw['snapshots']:
            if rnd.random()<0.7 and sp['bounds']:
                sp['bounds']=[[rnd.randint(0,2), min(10000, b[1]+rnd.randint(0,B))]
                              for b in sp['bounds']]
                sp['bounds']=[[min(a,b),max(a,b)] for a,b in sp['bounds']]
        if raw['domains'] and rnd.random()<0.5:
            raw['max_faults']=rnd.randint(0,len(raw['domains']))
        try:
            inst = parse_request(json.loads(json.dumps(raw)))
        except analyze.Invalid:
            print('INVALID GEN', json.dumps(raw)[:300]); bad+=1; continue
        exp = brute(inst)
        if exp is None:
            skipped+=1; continue
        done+=1
        st=time.time(); act=solve(inst); slowest=max(slowest,time.time()-st)
        errs = compare(exp, act)
        stats[exp['status']]=stats.get(exp['status'],0)+1
        if exp['status']!='infeasible':
            kstats[exp['min_faults']]=kstats.get(exp['min_faults'],0)+1
            try:
                check_witness(inst, act['witness'], act['min_faults'])
                if exp['status']=='unique':
                    if act['alternative'] is not None: errs.append(('alt-not-null',1,0))
                else:
                    if act['alternative'] is None: errs.append(('alt-missing',1,0))
                    else:
                        check_witness(inst, act['alternative'], act['min_faults'])
                        if act['witness']['demands']==act['alternative']['demands']:
                            errs.append(('alt-same',1,0))
            except AssertionError as e:
                errs.append(('witness',str(e)[:200],''))
        if errs:
            bad+=1
            print('MISMATCH', json.dumps(raw))
            print(' exp', json.dumps(exp)[:900]); print(' act', json.dumps(act)[:900])
            print(' errs', errs)
            if bad>2: break
    print('done %d (skipped %d), bad %d, %.1fs, stats=%s kstats=%s slowest=%.3f'%
          (done,skipped,bad,time.time()-t0,stats,kstats,slowest))

if __name__=='__main__': main()
